// ─── SPA Router ─────────────────────────────────────────────────

let currentPage = null;

function loadPage(pageName) {
  const page = PAGES[pageName];
  if (!page) { loadPage('index'); return; }

  currentPage = pageName;

  // Apply body CSS
  const styleEl = document.getElementById('page-body-style');
  styleEl.textContent = page.bodyCss
    .replace(/position:\s*relative;\s*/g, '')
    .replace(/left:-\d+px;\s*/g, '')
    .replace(/width:\d+px;\s*/g, '')
    .replace(/margin-left:\s*auto;\s*margin-right:\s*auto;\s*/g, '');

  // Render content
  document.getElementById('app').innerHTML = page.content;

  // Update title
  document.title = page.title + ' - 国男大冒险';

  // Update URL hash
  if (pageName !== 'index') {
    location.hash = '#/' + pageName;
  } else {
    location.hash = '';
  }

  // Attach click handlers to buttons
  const choices = NAV[pageName] || [];
  const buttons = document.querySelectorAll('.ax_default.button');
  buttons.forEach((btn, i) => {
    if (i < choices.length && choices[i].target) {
      btn.style.cursor = 'pointer';
      btn.addEventListener('click', () => loadPage(choices[i].target));
    }
  });

  // Fallback: if page has no choices and isn't index, show a back link
  if (pageName !== 'index' && choices.every(c => !c.target)) {
    const app = document.getElementById('app');
    const back = document.createElement('div');
    back.style.cssText = 'text-align:center;padding:2em;';
    back.innerHTML = '<a href="#" onclick="loadPage(\'index\');return false" style="font-size:18px;color:#02A7F0;text-decoration:none;">← 返回首页</a>';
    app.appendChild(back);
  }
}

// Handle hash changes
window.addEventListener('hashchange', () => {
  const page = location.hash.replace('#/', '');
  if (page && page !== currentPage) {
    loadPage(PAGES[page] ? page : 'index');
  }
});

// Boot from hash or index
const bootPage = location.hash.replace('#/', '');
loadPage(PAGES[bootPage] ? bootPage : 'index');
